        for ant in ants:
            if ant['active']:
                if ant['dir'][0] > 0:
                    dt = min(dt, (N - ant['pos'][0]) / ant['dir'][0])
                elif ant['dir'][0] < 0:
                    dt = min(dt, (0 - ant['pos'][0]) / ant['dir'][0])

                if ant['dir'][1] > 0:
                    dt = min(dt, (N - ant['pos'][1]) / ant['dir'][1])
                elif ant['dir'][1] < 0:
                    dt = min(dt, (0 - ant['pos'][1]) / ant['dir'][1])

